package com.cryptostrategy.platform.persistence.api;import com.cryptostrategy.platform.evaluation.api.port.out.EvaluationResultStore;import com.cryptostrategy.platform.persistence.internal.evaluation.JdbcEvaluationResultStore;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import javax.sql.DataSource;import java.util.Objects;public final class EvaluationPersistenceFactory{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public EvaluationPersistenceFactory(DataSource source){Objects.requireNonNull(source);jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));}public EvaluationResultStore createStore(){return new JdbcEvaluationResultStore(jdbc,tx);}}
